-- ============================================================
-- AI School - clean rebuild of the customer-service data (2026-10-09, v4)
-- Wipes: leads, bookings, their stage events / call attempts, teacher slots,
-- WhatsApp message log.  Keeps: users, finance, subscriptions (re-linked by
-- phone), teachers, WhatsApp templates and settings.
-- ONE ROW PER CUSTOMER (unique phone) in crm_leads, and one row per lecture
-- booking in crm_bookings - a customer can hold any number of bookings.
--   * every row of the «الحجوزات» sheet (212, with date / day / teacher) is a booking
--   * attendance is left blank - it is recorded by hand; عملاء مهتمون starts empty
--   * customers whose status in the customer file is «تم الحجز» but have no row in
--     the bookings sheet stay in العملاء المحتملون (note kept)
-- TAKE A DB BACKUP FIRST.
-- ============================================================
BEGIN;
DELETE FROM whatsapp_message_log;
DELETE FROM crm_bookings;
DELETE FROM crm_lead_call_attempts;
DELETE FROM crm_lead_stage_events;
DELETE FROM crm_teacher_slots;
DELETE FROM crm_leads;

DO $$
DECLARE admin_id uuid;
BEGIN
  SELECT id INTO admin_id FROM users ORDER BY created_at ASC LIMIT 1;
  IF admin_id IS NULL THEN RAISE EXCEPTION 'No user found to attribute import to'; END IF;

END $$;

-- subscriptions keep their own phone: re-link them to the rebuilt leads
UPDATE subscriptions s SET lead_id = (SELECT l.id FROM crm_leads l WHERE l.phone = s.phone ORDER BY l.created_at LIMIT 1);

-- the booking columns on crm_leads mirror each customer's latest booking
UPDATE crm_leads l SET teacher_slot_id = b.teacher_slot_id, teacher_name = b.teacher_name,
       lecture_date = b.lecture_date, lecture_time = b.lecture_time, zoom_link = b.zoom_link
FROM (SELECT DISTINCT ON (lead_id) * FROM crm_bookings ORDER BY lead_id, lecture_date DESC NULLS LAST, created_at DESC) b
WHERE b.lead_id = l.id;

-- checks
SELECT (SELECT count(*) FROM crm_leads) AS customers,
       (SELECT count(DISTINCT phone) FROM crm_leads) AS distinct_phones,
       (SELECT count(*) FROM crm_bookings) AS bookings,
       (SELECT count(*) FROM crm_bookings WHERE attended IS NULL) AS pending,
       (SELECT count(*) FROM crm_bookings WHERE attended IS TRUE) AS attended,
       (SELECT count(*) FROM crm_bookings WHERE attended IS FALSE) AS not_attended,
       (SELECT count(DISTINCT lead_id) FROM crm_bookings) AS customers_with_bookings;
COMMIT;
